# Instead: use bbox per connected same-color region; each bbox = a nested rectangle. For each rectangle (set of cells with that bbox): determine layers by distance to edge; build color stack from outside-in; then reassign reversed.
def process(I):
    H,W=len(I),len(I[0]); res=[row[:] for row in I]
    seen=set()
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and (i,j) not in seen:
                col=I[i][j]; comp={(i,j)}; st=[(i,j)]; 
                while st:
                    r,c=st.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=r+da,c+db
                        if 0<=x<H and 0<=y<W and (x,y) not in comp and I[x][y]==col:
                            comp.add((x,y)); st.append((x,y))
                rs=[r for r,_ in comp]; cs=[c for _,c in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                dvals={max(r-r0,r1-r,c-c0,c1-c) for r,c in comp}
                layers={}
                for k in dvals:
                    layers[k]=[]
                for r,c in comp: layers[max(r-r0,r1-r,c-c0,c1-c)].append(I[r][c])
                # order distinct ring values by k; build list of (color set) outward to inward, then reverse
                seq=[]
                for k in sorted(dvals): seq.append(layers[k])
                inv=list(reversed(seq))
                # assign back
                for k in dvals:
                    for r,c in comp:
                        if max(r-r0,r1-r,c-c0,c1-c)==k: res[r][c]=inv[k][0]
                for (r,c) in comp: seen.add((r,c))
    return res
