def solve(I):
    H,W=len(I),len(I[0]); res=[row[:] for row in I]; seen=set()
    # BFS from "outside": seed cells that have a neighbor outside the object (0-neighbor or off-grid), spread through nonzero cells.
    # Identify components of nonzero (4-conn), then flood within each comp from boundary cells.
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and (i,j) not in seen:
                col=None
                comp={(i,j)}; st=[(i,j)]
                while st:
                    r,c=st.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=r+da,c+db
                        if 0<=x<H and 0<=y<W and (x,y) not in comp and I[x][y]!=0:
                            comp.add((x,y)); st.append((x,y))
                seen.update(comp)
                # BFS from cells adjacent to 0/offgrid, depths through comp
                depth={}; q=collections.deque()
                for (r,c) in comp:
                    nb=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
                    if any(not(0<=x<H and 0<=y<W) or I[x][y]==0 for x,y in nb):
                        depth[(r,c)]=0; q.append((r,c))
                while q:
                    r,c=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=r+da,c+db
                        if (x,y) in comp and (x,y) not in depth:
                            depth[(x,y)]=depth[(r,c)]+1; q.append((x,y))
                maxd=max(depth.values())
                seq=[]
                for d in range(maxd+1):
                    vals=tuple(sorted({I[r][c] for r,c in comp if depth[(r,c)]==d}))
                    seq.append(vals)
                inv=seq[::-1]
                for r,c in comp:
                    res[r][c]=inv[depth[(r,c)]]
    return res
