def clusters(comps):
    # union-find on pairwise bbox strict-enclosure
    def rel(a,b):
        ar=[y for y,_ in a['cells']];cr=[x for _,x in a['cells']]
        br=[y for y,_ in b['cells']);bc=[x for _,x in b['cells']]
        return min(ar)>min(br) and max(ar)<max(br) and min(cr)>min(bc) and max(cr)<max(bc)
    parent={id(c):c for c in comps}
    import sys
    sys.setrecursionlimit(10**6)
    def root(c):
        while parent[id(c)]!=c: c=parent[id(c)]
        return c
    for i,a in enumerate(comps):
        for j,b in enumerate(comps):
            if rel(a,b) or rel(b,a):
                ra,rb=root(a),root(b)
                if ra!=rb: parent[ra]=rb
    gr={}
    for c in comps: gr.setdefault(root(c),[]).append(c)
    return [[list(v)] for v in gr.values()]  # flatten to lists

