def comps(g):
    H,W=len(g),len(g[0]); seen=set();res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and (i,j) not in seen:
                stack=[(i,j)];seen.add((i,j));cells=[]
                while stack:
                    y,x=stack.pop();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==g[i][j]:
                            seen.add((ny,nx));stack.append((ny,nx))
                res.append({'col':g[i][j],'cells':set(cells)})
    return res

